mapper.insert:
INSERT INTO knowledge_card(
    user_id, title, summary, source_log_id, tags_json, version, created_at, updated_at
)
VALUES(
    #{userId}, #{title}, #{summary}, #{sourceLogId}, #{tagsJson}, #{version}, #{createdAt}, #{updatedAt}
)
ON DUPLICATE KEY UPDATE id = LAST_INSERT_ID(id)

mapper.select:
SELECT id, title, summary, source_log_id, tags_json, review_stage, next_review_date, last_reviewed_at, created_at
FROM knowledge_card
WHERE user_id = #{userId} AND source_log_id = #{sourceLogId}

SELECT id, title, summary, source_log_id, tags_json, review_stage, next_review_date, last_reviewed_at, created_at
FROM knowledge_card
WHERE user_id = #{userId} AND id = #{id}

SELECT id, title, summary, source_log_id, tags_json, review_stage, next_review_date, last_reviewed_at, created_at
FROM knowledge_card
WHERE user_id = #{userId}
ORDER BY created_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM knowledge_card
WHERE user_id = #{userId}

SELECT id, title, summary, source_log_id, tags_json, review_stage, next_review_date, last_reviewed_at, created_at
FROM knowledge_card
WHERE user_id = #{userId}
  AND next_review_date IS NOT NULL AND next_review_date <= #{date}
ORDER BY next_review_date ASC, id ASC
LIMIT #{limit}

mapper.update:
UPDATE knowledge_card
SET review_stage = #{reviewStage}, next_review_date = #{nextReviewDate},
    last_reviewed_at = #{lastReviewedAt}, updated_at = #{lastReviewedAt}
WHERE id = #{id} AND user_id = #{userId}

UPDATE knowledge_card
SET title = #{title}, summary = #{summary}, tags_json = #{tagsJson},
    version = version + 1, updated_at = #{updatedAt}
WHERE id = #{id} AND user_id = #{userId}
